def set_cell_shading(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr(); shd = OxmlElement('w:shd'); shd.set(qn('w:fill'), fill); tcPr.append(shd)

def set_repeat_table_header(row):
    trPr = row._tr.get_or_add_trPr(); e = OxmlElement('w:tblHeader'); e.set(qn('w:val'), 'true'); trPr.append(e)

def set_cell_margins(cell, top=100, start=120, bottom=100, end=120):
    tc = cell._tc; tcPr = tc.get_or_add_tcPr(); mar = tcPr.first_child_found_in('w:tcMar')
    if mar is None: mar = OxmlElement('w:tcMar'); tcPr.append(mar)
    for side, value in [('top', top), ('start', start), ('bottom', bottom), ('end', end)]:
        node = mar.find(qn(f'w:{side}'))
        if node is None: node = OxmlElement(f'w:{side}'); mar.append(node)
        node.set(qn('w:w'), str(value)); node.set(qn('w:type'), 'dxa')

def set_font(run, size=12, bold=False, italic=False):
    run.font.name = 'Times New Roman'; run._element.rPr.rFonts.set(qn('w:ascii'), 'Times New Roman'); run._element.rPr.rFonts.set(qn('w:hAnsi'), 'Times New Roman')
    run.font.size = Pt(size); run.bold = bold; run.italic = italic; run.font.color.rgb = RGBColor(0,0,0)

def field(paragraph, instr):
    r = paragraph.add_run(); fld = OxmlElement('w:fldChar'); fld.set(qn('w:fldCharType'), 'begin'); r._r.append(fld)
    r2 = paragraph.add_run(); it = OxmlElement('w:instrText'); it.set(qn('xml:space'), 'preserve'); it.text = instr; r2._r.append(it)
    r3 = paragraph.add_run(); sep = OxmlElement('w:fldChar'); sep.set(qn('w:fldCharType'), 'separate'); r3._r.append(sep)
    paragraph.add_run('1'); r4 = paragraph.add_run(); end = OxmlElement('w:fldChar'); end.set(qn('w:fldCharType'), 'end'); r4._r.append(end)

def page_number(section):
    p = section.footer.paragraphs[0]; p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    field(p, 'PAGE')
    for r in p.runs: set_font(r, 12)

def add_para(doc, text='', align=None, before=0, after=8, first=True, italic=False, boldlead=None):
    p = doc.add_paragraph(); p.paragraph_format.line_spacing = 1.5; p.paragraph_format.space_before = Pt(before); p.paragraph_format.space_after = Pt(after)
    if first: p.paragraph_format.first_line_indent = Cm(1.0)
    if align is not None: p.alignment = align
    if boldlead and text.startswith(boldlead):
        r = p.add_run(boldlead); set_font(r, 12, bold=True)
        r = p.add_run(text[len(boldlead):]); set_font(r, 12, italic=italic)
    else:
        r=p.add_run(text); set_font(r, 12, italic=italic)
    return p

def add_heading(doc, text, level=1, chapter=False):
    p=doc.add_paragraph(); p.paragraph_format.space_before=Pt(8); p.paragraph_format.space_after=Pt(14); p.paragraph_format.keep_with_next=True
    p.alignment=WD_ALIGN_PARAGRAPH.CENTER if chapter else WD_ALIGN_PARAGRAPH.LEFT
    r=p.add_run(text.upper()); set_font(r, 16 if chapter else (14 if level==1 else 12), bold=chapter)
    return p

def add_table(doc, headers, rows, widths=None):
    t=doc.add_table(rows=1, cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'; t.autofit=False
    set_repeat_table_header(t.rows[0])
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i]; set_cell_shading(c,'1F4E78'); set_cell_margins(c); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        p=c.paragraphs[0]; p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(h); set_font(r,10,bold=True); r.font.color.rgb=RGBColor(255,255,255)
        if widths: c.width=Cm(widths[i])
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        for i,val in enumerate(row):
            c=cells[i]; set_cell_margins(c); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            if ri%2: set_cell_shading(c,'EAF2F8')
            p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0); p.paragraph_format.line_spacing=1.0
            r=p.add_run(str(val)); set_font(r,10)
            if widths: c.width=Cm(widths[i])
    doc.add_paragraph().paragraph_format.space_after=Pt(2)
    return t

