    if figure and IMG.exists():
        p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(); r.add_picture(str(IMG),width=Inches(5.7))
        p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run('Figure [PUT FIGURE NUMBER HERE]: TwinHealth AI system block diagram'); set_font(r,10,italic=True)
    if note: add_para(doc,note,after=0,boldlead='[PUT ')
    page(doc)

